import tempfile
import unittest
from pathlib import Path

from parse_uae_isogen_neutral import audit_file, parse_line


# Literal source rows, not rows generated by the parser's schema.
BOLT = 'BOLT  608200   H4-P  PAA 213-0212-HCX-PAA     213-0212-HCX             52   999           0                         STU   CC1L6D-FA       22.225MM150.0   8'
GASKET = 'GASK  608200   H4-P  PAA 213-0212-HCX-PAA     213-0212-HCX             52   999           0                         GASD  CC1L6D-FA       4.0IN           1'
SUPPORT = 'SUPP  608200   H4-P  PAA 213-0212-HCX-PAA     213-0212-HCX             52   999           0                               CC1L6D-FA       4.0IN           1                                                                           SW-300-100-4"-C.S.'


class NeutralParserTests(unittest.TestCase):
    def test_adjacent_bolt_fields(self):
        row = parse_line(BOLT)
        self.assertEqual((row['size_1'], row['size_2'], row['quantity_or_length']), ('22.225MM', '150.0', '8'))

    def test_empty_middle_and_trimmed_tail(self):
        row = parse_line(GASKET)
        self.assertEqual(row['size_2'], '')
        self.assertEqual(row['quantity_or_length'], '1')
        self.assertEqual(row['end_preparation'], '')
        self.assertEqual(row['support_code'], '')
        self.assertEqual(len(row), 16)

    def test_support_with_blank_commodity(self):
        row = parse_line(SUPPORT)
        self.assertEqual(row['commodity_code'], '')
        self.assertEqual(row['end_preparation'], '')
        self.assertEqual(row['support_code'], 'SW-300-100-4"-C.S.')

    def test_shift_rejected(self):
        for bad in (' ' + BOLT, BOLT[:100] + BOLT[101:], BOLT.replace('22.225MM150.0', '22.225MM 150.0')):
            with self.subTest(bad=bad), self.assertRaises(ValueError):
                parse_line(bad)

    def test_tabs_nonascii_and_truncation(self):
        for bad in (BOLT.replace('  ', '\t', 1), BOLT[:138] + '口径' + BOLT[140:], BOLT[:150], BOLT + '\x00'):
            with self.subTest(bad=bad), self.assertRaises(ValueError):
                parse_line(bad)

    def test_pcf_multiplicity_and_ambiguous_uci(self):
        with tempfile.TemporaryDirectory() as temp:
            root = Path(temp)
            txt = root / '4-213-52-0212-HCX-PAA-isogen-neutral1.txt'
            pcf = root / '4-213-52-0212-HCX-PAA-pcf.pcf'
            txt.write_text(GASKET + '\n' + GASKET + '\n', encoding='ascii')
            pcf.write_text('PIPELINE-REFERENCE 4-213-52-0212-HCX-PAA\n    LINE-ID 213-0212-HCX\n    ATTRIBUTE51 0\n' + ''.join(
                f'GASKET\n    COMPONENT-IDENTIFIER {i}\n    UCI {{test-{i}}}\n'
                '    COMPONENT-ATTRIBUTE31 GASK  608200   H4-P  PAA 213-0212-HCX-PAA     213-0212-HCX             52   999\n'
                '    COMPONENT-ATTRIBUTE32 GASD\n'
                '    COMPONENT-ATTRIBUTE33 CC1L6D-FA       4.0IN           1\n'
                for i in (1, 2)) + 'MATERIALS\n', encoding='ascii')
            rows, report = audit_file(txt)
            self.assertEqual(report['status'], '通过')
            self.assertEqual(len(rows[0]['pcf_candidates']), 2)
            txt.write_text(GASKET + '\n', encoding='ascii')
            _, report = audit_file(txt)
            self.assertEqual(report['status'], '失败')
            self.assertEqual(len(report['missing_rows']), 1)

    def test_missing_pcf_not_claimed_verified(self):
        with tempfile.TemporaryDirectory() as temp:
            txt = Path(temp) / 'example-isogen-neutral1.txt'
            txt.write_text(BOLT, encoding='ascii')
            rows, report = audit_file(txt)
            self.assertEqual(report['status'], '未验证')
            self.assertEqual(rows[0]['status'], '仅格式通过')

    def test_pcf_without_report_attributes_is_not_success(self):
        with tempfile.TemporaryDirectory() as temp:
            txt = Path(temp) / 'example-isogen-neutral1.txt'
            txt.write_text(BOLT, encoding='ascii')
            txt.with_name('example-pcf.pcf').write_text('PIPELINE-REFERENCE example\n    ATTRIBUTE51 0\nMATERIALS\n', encoding='ascii')
            _, report = audit_file(txt)
            self.assertEqual(report['status'], '失败')

    def test_valid_but_changed_value_fails_pcf_check(self):
        # A plausible value change cannot be detected by column validation alone.
        self.assertEqual(parse_line(BOLT.replace('150.0', '160.0'))['size_2'], '160.0')
        with tempfile.TemporaryDirectory() as temp:
            txt = Path(temp) / '4-213-52-0212-HCX-PAA-isogen-neutral1.txt'
            pcf = Path(temp) / '4-213-52-0212-HCX-PAA-pcf.pcf'
            txt.write_text(BOLT.replace('150.0', '160.0'), encoding='ascii')
            pcf.write_text('PIPELINE-REFERENCE 4-213-52-0212-HCX-PAA\n    LINE-ID 213-0212-HCX\n    ATTRIBUTE51 0\nBOLT\n'
                '    COMPONENT-ATTRIBUTE31 BOLT  608200   H4-P  PAA 213-0212-HCX-PAA     213-0212-HCX             52   999\n'
                '    COMPONENT-ATTRIBUTE32 STU\n    COMPONENT-ATTRIBUTE33 CC1L6D-FA       22.225MM150.0   8\nMATERIALS\n', encoding='ascii')
            rows, report = audit_file(txt)
            self.assertEqual(report['status'], '失败')
            self.assertEqual(rows[0]['status'], '错误')


if __name__ == '__main__':
    unittest.main()
